func TestScratchProbeParametersField(t *testing.T) {
	cases := []struct{ path, src string }{
		{"a.go", "package p\nfunc (c *Client) Do(ctx context.Context, name string, opts map[string]int) error { return nil }\n"},
		{"a.zig", "fn caller(b: *Build, options: struct { scripts: u8, git_commit: u8 }) void {}\n"},
		{"a.py", "def f(a, b=1, *args, **kw):\n    pass\n"},
		{"a.rs", "fn f(a: u8, b: Vec<(u8, u8)>) -> u8 { a }\n"},
		{"a.java", "class C { void m(int a, Map<String, Integer> b) {} }\n"},
		{"a.rb", "def f(a, b = 1)\nend\n"},
		{"a.ts", "function f(a: number, {x, y}: P): void {}\n"},
	}
	for _, tc := range cases {
		spec, ok := languageForPath(tc.path)
		if !ok {
			fmt.Printf("%-8s NO SPEC\n", tc.path)
			continue
		}
		parser := sitter.NewParser()
		parser.SetLanguage(spec.grammar)
		tree, err := parser.ParseCtx(context.Background(), nil, []byte(tc.src))
		if err != nil || tree == nil {
			fmt.Printf("%-8s parse failed\n", tc.path)
			parser.Close()
			continue
		}
		var found string
		var walk func(n *sitter.Node)
		walk = func(n *sitter.Node) {
			if found != "" || n == nil || n.IsNull() {
				return
			}
			if p := n.ChildByFieldName("parameters"); p != nil && !p.IsNull() {
				found = fmt.Sprintf("node=%-28s parameters=%-20s text=%q", n.Type(), p.Type(), p.Content([]byte(tc.src)))
				return
			}
			for i := 0; i < int(n.NamedChildCount()); i++ {
				walk(n.NamedChild(i))
			}
		}
		walk(tree.RootNode())
		if found == "" {
			found = "NO `parameters` FIELD ANYWHERE"
		}
		fmt.Printf("%-8s %s | %s\n", tc.path, spec.language, found)
		tree.Close()
		parser.Close()
	}
}
