func TestScratchProbeGrammarShapes(t *testing.T) {
	paramNodeTypes := map[string]bool{
		"parameters": true, "parameter_list": true, "formal_parameters": true,
		"method_parameters": true, "parameter_declaration_list": true,
		"function_value_parameters": true, "parameter_clause": true,
		"argument_list": true, "block_parameters": true,
	}
	for _, tc := range paramSamples {
